// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    MultiplicatorX3 c;
    Receiver r;

    function setUp() public {
        c = new MultiplicatorX3();
        r = new Receiver();
    }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount <= 1e30);
        vm.deal(address(this), amount);
        uint256 before = address(c).balance;
        c.Command{value: amount}(address(r), "");
        // Rule: forwarding the full attached value leaves c's balance unchanged.
        assertTrue(address(c).balance == before);
    }
}

contract Receiver {
    receive() external payable {}
}
